-- Upsert script: Insert or update plant_timelines with proper conflict handling
-- Uses ON CONFLICT DO UPDATE to handle existing records

INSERT INTO plant_timelines (plant_name, au_hardiness_zone, sow_to_seedling, seedling_to_harvest, harvest_window, growth_multiplier, watering_frequency, extra_care, key_activities)
VALUES
('Tomatoes', '8a', 21, 60, 45, 1.2, 4, ARRAY['Use frost protection when needed','Monitor night temperatures'], '[{"timing":21,"activity":"Fertilise","details":"Use balanced 5-5-5 organic fertilizer, apply 2 tablespoons per plant in a ring 4 inches from stem. Water thoroughly after application to avoid root burn.","category":"fertilizing"},{"timing":28,"activity":"Monitor for pests","details":"Check undersides of leaves daily for hornworms (green with white stripes, up to 4 inches long) and aphids (small, clustered). Look for holes or stippled yellow damage. Hand-pick hornworms or use Bt spray. For aphids, spray with neem oil or insecticidal soap every 7 days as needed.","category":"pest"},{"timing":35,"activity":"Install supports","details":"Place cage (at least 5-6 feet tall) or drive 6-foot wooden stakes 8 inches into ground, 4 inches from stem base. Use soft ties to loosely tie stems every 12 inches as plant grows. Stakes must support 20-30 pounds of fruit.","category":"planting"},{"timing":45,"activity":"Remove suckers and lower leaves","details":"Remove side shoots (suckers) growing in crotch between main stem and branches to direct energy to fruit. Remove all leaves touching ground or within 12 inches of soil to improve air circulation and reduce disease.","category":"pruning"},{"timing":60,"activity":"Check first fruits for ripeness","details":"Fruits are ready when they reach full color for variety (deep red, orange, pink, or yellow depending on type) and feel slightly soft to gentle pressure. Pick in morning when cool. Fully ripe tomatoes develop best flavor.","category":"harvest"}]'::jsonb),
