('Tomatoes', '12b', 21, 60, 45, 0.75, 2, ARRAY['Year-round growing potential','Shade critical for many crops'], '[{"timing":21,"activity":"Fertilise","details":"Use balanced 5-5-5 organic fertilizer, apply 2 tablespoons per plant in a ring 4 inches from stem. Water thoroughly after application to avoid root burn.","category":"fertilizing"},{"timing":28,"activity":"Monitor for pests","details":"Check undersides of leaves daily for hornworms (green with white stripes, up to 4 inches long) and aphids (small, clustered). Look for holes or stippled yellow damage. Hand-pick hornworms or use Bt spray. For aphids, spray with neem oil or insecticidal soap every 7 days as needed.","category":"pest"},{"timing":35,"activity":"Install supports","details":"Place cage (at least 5-6 feet tall) or drive 6-foot wooden stakes 8 inches into ground, 4 inches from stem base. Use soft ties to loosely tie stems every 12 inches as plant grows. Stakes must support 20-30 pounds of fruit.","category":"planting"},{"timing":45,"activity":"Remove suckers and lower leaves","details":"Remove side shoots (suckers) growing in crotch between main stem and branches to direct energy to fruit. Remove all leaves touching ground or within 12 inches of soil to improve air circulation and reduce disease.","category":"pruning"},{"timing":60,"activity":"Check first fruits for ripeness","details":"Fruits are ready when they reach full color for variety (deep red, orange, pink, or yellow depending on type) and feel slightly soft to gentle pressure. Pick in morning when cool. Fully ripe tomatoes develop best flavor.","category":"harvest"}]'::jsonb),
('Lettuce', '8a', 7, 45, 30, 0.95, 4, ARRAY['Protect from frost','Use row covers'], '[{"timing":7,"activity":"Ensure moist soil","details":"Keep soil consistently moist but not waterlogged. Lettuce prefers cool, moist conditions. Water gently with fine spray. Mulch lightly to retain moisture and keep roots cool.","category":"watering"},{"timing":14,"activity":"Thin seedlings","details":"When seedlings have 2-3 true leaves, thin to 6-8 inches apart (head lettuce) or 4-6 inches (leaf lettuce). Cut rather than pull to avoid root disturbance. Thinned seedlings are edible.","category":"planting"},{"timing":28,"activity":"Monitor for pests","details":"Check for lettuce aphids, slugs, and snails. Inspect leaf undersides and soil around plants. Hand-pick slugs in early morning or evening. Use slug traps or netting if needed.","category":"pest"},{"timing":35,"activity":"Begin harvesting outer leaves","details":"For leaf lettuce, begin harvesting outer leaves when 4-6 inches long. Pick in morning for crispest texture. Pinch off outer leaves leaving center to continue growing. Regular harvesting delays bolting.","category":"harvest"},{"timing":45,"activity":"Harvest head lettuce or cut entire plant","details":"Head lettuce: cut when head feels firm. Leaf lettuce: continue picking outer leaves. Once plant bolts, harvest is over. Cooler weather extends season.","category":"harvest"}]'::jsonb),
