ON CONFLICT (plant_name, au_hardiness_zone)
DO UPDATE SET
  sow_to_seedling = EXCLUDED.sow_to_seedling,
  seedling_to_harvest = EXCLUDED.seedling_to_harvest,
  harvest_window = EXCLUDED.harvest_window,
  growth_multiplier = EXCLUDED.growth_multiplier,
  watering_frequency = EXCLUDED.watering_frequency,
  extra_care = EXCLUDED.extra_care,
  key_activities = EXCLUDED.key_activities,
  updated_at = NOW();

-- Create indexes for performance (if they don't exist)
CREATE INDEX IF NOT EXISTS idx_plant_timelines_zone ON plant_timelines(au_hardiness_zone);
CREATE INDEX IF NOT EXISTS idx_plant_timelines_name ON plant_timelines(plant_name);
CREATE INDEX IF NOT EXISTS idx_plant_timelines_composite ON plant_timelines(plant_name, au_hardiness_zone);

-- Verify results
SELECT COUNT(*) as total_records, COUNT(DISTINCT plant_name) as unique_plants, COUNT(DISTINCT au_hardiness_zone) as zones FROM plant_timelines WHERE plant_name IN ('Tomatoes', 'Lettuce');
